Slice<E> SortedFunc<E>(
  Dict<E> $dE,
  void Function(bool Function(E)?)? seq,
  int Function(E, E)? cmp,
) {
  Slice<E> out = Collect<E>($dE, seq);
  SortFunc<Slice<E>, E>(
    Dict<Slice<E>>(
      () => Slice<E>.nil(),
      (a, b) => a == b,
      (v) => v.hashCode,
      (n) => List<Slice<E>>.generate(n, (_) => Slice<E>.nil()),
      $unordered<Slice<E>>,
      $identity<Slice<E>>,
      TypeDesc(
        '[]E',
        'slice',
        const <String, Function>{},
        text: '[]E',
        elem: () => $dE.desc,
        make: ($n) => $makeSlice<E>($n, $n, $dE.alloc),
        comparable: false,
        zero: () => Slice<E>.nil(),
      ),
    ),
    $dE,
    out,
    cmp,
  );
  return out;
}

Slice<E> SortedStableFunc<E>(
  Dict<E> $dE,
  void Function(bool Function(E)?)? seq,
  int Function(E, E)? cmp,
) {
  return SortedFunc<E>($dE, seq, cmp);
}

void Function(bool Function(Slice<E>)?)? Chunk<S extends Slice<E>, E>(
  Dict<Slice<E>> $dS,
  Dict<E> $dE,
  Slice<E> s,
  int n,
) {
  if ((n < 1)) {
    $panic(Iface($typeString, GoString.fromString('cannot be less than 1')));
  }
  return (bool Function(Slice<E>)? yield$) {
    for (int i = 0; (i < s.len); i = (i + n)) {
      int end = (i + n);
      if ((end > s.len)) {
        end = s.len;
      }
      if ((!yield$!(s.range(i, end, end)))) {
        return;
      }
    }
  };
}
